const queryClient = new QueryClient();
const PublicSettingsContext = createContext({ whatsappNumber: "", phoneNumber: "" });

type FormData = {
  city: string; urgency: string; needs: string[]; languagePreference: string;
  saudiExperiencePreference: string; nationalityPreference: string; readiness: string;
  name: string; phone: string; consent: boolean;
};
type Worker = {
  id: string; publicCode: string; slug: string; name: string; origin: string; nationalitySlug: string; experience: string; languages: string[];
  skills: string[]; availability: string; availabilityStatus: string; color: string; initials: string; story: string; imageUrl?: string; requestable: boolean;
};

const initialForm: FormData = { city: "", urgency: "", needs: [], languagePreference: "", saudiExperiencePreference: "", nationalityPreference: "", readiness: "", name: "", phone: "", consent: false };
const workerColors = ["#d9bfae", "#b8cec1", "#d1c6a5", "#cab8c5"];

function mapWorker(worker: ApiWorker, index = 0): Worker {
  const availabilityLabels: Record<string, string> = { AVAILABLE: "متاحة للتواصل", ON_HOLD: "متوقفة مؤقتاً", RESERVED: "محجوزة", TRANSFER_IN_PROGRESS: "إجراءات النقل جارية", TRANSFERRED: "تم النقل", UNAVAILABLE: "غير متاحة" };
  return { id: worker.publicCode, publicCode: worker.publicCode, slug: worker.slug, name: worker.displayName, origin: worker.nationality.nameAr || worker.nationality.nameEn, nationalitySlug: worker.nationality.slug, experience: worker.yearsExperience ? `${worker.yearsExperience} سنوات خبرة` : "خبرة منزلية موثقة", languages: worker.languages, skills: worker.skills, availabilityStatus: worker.availabilityStatus, availability: availabilityLabels[worker.availabilityStatus] || "متاحة للتواصل", color: workerColors[index % workerColors.length], initials: worker.displayName.trim().slice(0, 1), story: worker.summary || "ملف تعريفي مختصر. التفاصيل المناسبة تبدأ بالحوار.", imageUrl: worker.media.find((item) => item.isPrimary)?.url || worker.media[0]?.url, requestable: worker.availabilityStatus === "AVAILABLE" };
}

function cn(...classes: Array<string | false | null | undefined>) { return classes.filter(Boolean).join(" "); }
function Logo({ light = false }: { light?: boolean }) {
  return <div className="flex items-center gap-3" dir="rtl">
    <span className={cn("flex h-10 w-10 items-center justify-center rounded-[14px] font-display text-lg font-bold", light ? "bg-[#ead9ae] text-[#164a43]" : "bg-[#164a43] text-[#f5ead0]")}>ع</span>
    <span className={cn("leading-none", light ? "text-[#f7f3e9]" : "text-[#164a43]")}>
      <strong className="block font-display text-[18px] tracking-normal">عهد</strong>
      <small className={cn("mt-1 block text-[9px] tracking-normal", light ? "text-[#b6c9bf]" : "text-[#52665d]")}>AHD</small>
    </span>
  </div>;
}

type Navigate = (path: string) => void;
function Header({ path, navigate, dark = false }: { path: string; navigate: Navigate; dark?: boolean }) {
  const [open, setOpen] = useState(false);
  const links = [["الرئيسية", "/home"], ["اكتشف الخيارات", "/catalogue"], ["كيف نساعدك؟", "/help"]];
  return <header className={cn("relative z-30 px-5 py-5 md:px-10", dark ? "text-[#f7f3e9]" : "text-[#164a43]")}>
    <div className="mx-auto flex max-w-[1240px] items-center justify-between">
      <button data-testid="button-logo" onClick={() => navigate(dark ? "/" : "/home")} aria-label="العودة للرئيسية"><Logo light={dark} /></button>
      <nav className={cn("hidden items-center gap-8 text-sm font-medium md:flex", dark ? "text-[#c8d6cf]" : "text-[#5b7067]")}>
        {links.map(([label, target]) => <button data-testid={`nav-${target.slice(1)}`} key={target} onClick={() => navigate(target)} className={cn("relative py-2 transition hover:text-[#b58b4b]", path === target && "text-[#b58b4b]")}>{label}</button>)}
      </nav>
      <div className="flex items-center gap-3">
        <button data-testid="button-help-header" onClick={() => navigate("/help")} className={cn("hidden rounded-full px-5 py-2.5 text-[13px] font-bold transition md:block", dark ? "border border-[#77958a] text-[#f7f3e9] hover:bg-[#285d54]" : "bg-[#164a43] text-[#f7f3e9] hover:bg-[#0e3b35]")}>أحتاج مساعدة</button>
        <button data-testid="button-mobile-menu" onClick={() => setOpen(!open)} aria-label={open ? "إغلاق القائمة" : "فتح القائمة"} className={cn("flex h-10 w-10 items-center justify-center rounded-full md:hidden", dark ? "border border-[#77958a]" : "border border-[#ced8ce]")}>{open ? <X size={19} /> : <Menu size={19} />}</button>
      </div>
    </div>
    {open && <div className="absolute left-5 right-5 top-[76px] rounded-2xl border border-[#d5ddd4] bg-[#fbfaf6] p-3 text-[#164a43] shadow-[0_18px_50px_rgba(22,54,46,.14)] md:hidden">
      {links.map(([label, target]) => <button data-testid={`mobile-nav-${target.slice(1)}`} key={target} onClick={() => { navigate(target); setOpen(false); }} className="flex w-full items-center justify-between rounded-xl px-4 py-3 text-right text-sm hover:bg-[#eef3ed]">{label}<ChevronLeft size={16} /></button>)}
      <button data-testid="mobile-help-header" onClick={() => { navigate("/help"); setOpen(false); }} className="mt-1 w-full rounded-xl bg-[#164a43] px-4 py-3 text-right text-sm font-bold text-[#f7f3e9]">أحتاج مساعدة</button>
    </div>}
  </header>;
}

function Pill({ children, dark = false }: { children: ReactNode; dark?: boolean }) {
  return <span className={cn("inline-flex items-center rounded-full px-3 py-1.5 text-[11px] font-medium", dark ? "bg-[#285d54] text-[#d8e7dd]" : "bg-[#e7efe6] text-[#376057]")}>{children}</span>;
}

function Footer({ navigate }: { navigate: Navigate }) {
  const { phoneNumber } = useContext(PublicSettingsContext);
  const phoneHref = phoneNumber.replace(/[^+\d]/g, "");
  return <footer className="border-t border-[#dbe1d8] bg-[#edf1e9] px-5 py-10 text-[#164a43] md:px-10">
    <div className="mx-auto flex max-w-[1240px] flex-col justify-between gap-8 md:flex-row md:items-end"><div><Logo /><p className="mt-4 max-w-xs text-sm leading-7 text-[#64766f]">نساعدك تبدأ بخطوة واضحة، وتكمل التفاصيل بالطريقة التي تناسبك.</p></div>
      <div className="flex flex-wrap gap-x-7 gap-y-3 text-sm text-[#526660]"><button data-testid="footer-home" onClick={() => navigate("/home")}>الرئيسية</button><button data-testid="footer-catalogue" onClick={() => navigate("/catalogue")}>الخيارات</button><button data-testid="footer-help" onClick={() => navigate("/help")}>الأسئلة الشائعة</button>{phoneHref && <a data-testid="footer-phone" href={`tel:${phoneHref}`} onClick={() => trackEvent("phone_clicked")} className="inline-flex items-center gap-2"><Phone size={15} />اتصل بنا</a>}</div>
    </div>
    <div className="mx-auto mt-8 max-w-[1240px] border-t border-[#d5ddd5] pt-5 text-xs text-[#7a8983]">عهد — بيانات العاملات المنشورة يحدّثها فريق الإدارة.</div>
  </footer>;
}

function Landing({ navigate }: { navigate: Navigate }) {
  const [content, setContent] = useState<Record<string, unknown>>({});
  useEffect(() => { trackEvent("transfer_lp_viewed"); getContent<Record<string, unknown>>("transferLanding").then((block) => setContent(block.contentAr || {})).catch(() => undefined); }, []);
  const text = (key: string, fallback: string) => typeof content[key] === "string" && String(content[key]).trim() ? String(content[key]) : fallback;
  return <div dir="rtl" className="relative min-h-[100dvh] overflow-x-clip bg-[#164a43] text-[#f7f3e9]">
    <div className="pointer-events-none absolute inset-0"><div className="absolute -left-24 top-12 h-72 w-72 rounded-full border border-[#6d9183]/30" /><div className="absolute -left-10 top-28 h-52 w-52 rounded-full border border-[#6d9183]/25" /><div className="absolute bottom-16 right-[-90px] h-72 w-72 rounded-full border border-[#6d9183]/20" /></div>
    <Header path="/" navigate={navigate} dark />
    <main className="relative mx-auto max-w-[1240px] px-5 pb-14 pt-10 md:px-10 md:pb-24 md:pt-20">
      <div className="grid items-center gap-14 lg:grid-cols-[1.02fr_.98fr]">
        <section className="animate-rise-in max-w-[660px]"><div className="mb-8 flex items-center gap-3 text-xs text-[#a9c0b5]"><span className="h-px w-10 bg-[#d6b56d]" /><span>{text("heroEyebrow", "خدمة مدفوعة · نقل خدمات منزلية")}</span></div>
          <h1 className="font-display max-w-[620px] text-[40px] font-bold leading-[1.35] tracking-[-.05em] md:text-[64px]">{text("heroTitle", "احتياج بيتك")}<br /><span className="text-[#ead9ae]">{text("heroAccent", "له خيار مناسب.")}</span></h1>
          <p className="mt-7 max-w-[530px] text-[16px] leading-8 text-[#c4d3cb] md:text-[18px]">{text("heroBody", "إذا كنت تبحث عن نقل خدمات عاملة منزلية، صف لنا ما تحتاجه ونرتّب لك بداية واضحة لمراجعة الخيارات المناسبة. القرار لك، والتواصل يتم بالطريقة التي تريحك.")}</p>
          <button data-testid="button-start-match" onClick={() => { trackEvent("matching_cta_clicked"); navigate("/match/1"); }} className="mt-9 inline-flex items-center gap-3 rounded-full bg-[#ead9ae] px-7 py-4 text-[15px] font-bold text-[#164a43] shadow-[0_10px_30px_rgba(0,0,0,.12)] transition hover:-translate-y-0.5 hover:bg-[#f3e5bf]">ابدأ طلب المطابقة<ArrowLeft size={18} /></button>
          <div className="mt-12 flex flex-wrap gap-x-7 gap-y-3 text-xs text-[#abc0b5]"><span className="flex items-center gap-2"><ShieldCheck size={15} className="text-[#ead9ae]" /> معلوماتك تُستخدم لفهم احتياجك</span><span className="flex items-center gap-2"><MessageCircle size={15} className="text-[#ead9ae]" /> يمكنك إكمال الحديث عبر واتساب</span></div>
        </section>
        <section className="animate-rise-in delay-1 relative lg:pr-10"><div className="relative mx-auto max-w-[470px] rounded-[32px] border border-[#6d9183]/50 bg-[#20564e] p-5 md:p-7"><div className="absolute -left-6 top-12 hidden rounded-2xl border border-[#6d9183]/50 bg-[#164a43] px-4 py-3 text-xs text-[#e1e9e1] shadow-lg md:block"><span className="mb-2 block text-[#a9c0b5]">نبدأ من</span><strong className="text-sm text-[#ead9ae]">احتياجك الفعلي</strong></div>
            <div className="rounded-[24px] bg-[#f7f3e9] p-5 text-[#164a43] md:p-7"><div className="flex items-center justify-between border-b border-[#dce1d8] pb-5"><div><span className="text-[11px] text-[#7a8b83]">رحلة المطابقة</span><h2 className="mt-1 font-display text-lg font-bold">من الاحتياج إلى القرار</h2></div><div className="flex h-11 w-11 items-center justify-center rounded-2xl bg-[#ead9ae] text-lg font-bold">خ</div></div>
              <div className="space-y-0 pt-6">{[["01", "احتياجك", "تفاصيل البيت وما يهمك"], ["02", "الخيارات", "نراجع ما يناسب وصفك"], ["03", "التفاصيل", "تواصل واضح ومباشر"], ["04", "القرار", "تختار الخطوة التالية"]].map(([number, title, copy], index) => <div key={title} className="relative flex gap-4 pb-6 last:pb-0">{index < 3 && <span className="absolute right-[15px] top-8 h-full w-px bg-[#dce1d8]" />}<span className={cn("relative z-10 flex h-8 w-8 shrink-0 items-center justify-center rounded-full text-[10px] font-bold", index === 0 ? "bg-[#164a43] text-[#f7f3e9]" : "bg-[#e7eee6] text-[#5f766d]")}>{number}</span><div><h3 className="text-sm font-bold">{title}</h3><p className="mt-1 text-xs text-[#778780]">{copy}</p></div></div>)}</div>
            </div><div className="mt-5 flex items-center justify-between px-1 text-xs text-[#bbd0c4]"><span>تجربة مرتبة، بدون استعجال</span><Sparkles size={15} className="text-[#ead9ae]" /></div>
          </div></section>
      </div>
      <div className="mt-20 grid gap-5 border-t border-[#4e766a] pt-8 md:grid-cols-3">{[["لا نقرر عنك", "نرتب الصورة، وتبقى الخطوة الأخيرة بيدك."], ["نسمع التفاصيل", "الاختيار الأفضل يبدأ من يومك كما هو، لا من قائمة عامة."], ["تواصل على راحتك", "بعد الطلب، يمكنك متابعة الحديث عبر واتساب."]].map(([title, copy]) => <div key={title}><h3 className="text-sm font-bold text-[#ead9ae]">{title}</h3><p className="mt-2 text-sm leading-7 text-[#b5c9bf]">{copy}</p></div>)}</div>
    </main>
    <LandingDetails navigate={navigate} content={content} />
  </div>;
}

function LandingDetails({ navigate, content }: { navigate: Navigate; content: Record<string, unknown> }) {
  const start = () => { trackEvent("matching_cta_clicked"); navigate("/match/1"); };
  const defaultFaqs = [
    ["هل هذه خدمة استقدام؟", "هذه الصفحة مخصصة لطلبات نقل الخدمات. نبدأ بفهم الاحتياج، ثم نراجع الخيارات المتاحة التي يمكن أن تناسبه."],
    ["هل أحتاج لاختيار عاملة قبل البدء؟", "لا. طلب المطابقة يبدأ من احتياج البيت، ولا يشترط تصفح الكتالوج أو تحديد عاملة بعينها."],
    ["كيف أعرف التكلفة؟", "تختلف التفاصيل باختلاف الخيار وحالة النقل. نوضح المعلومات المرتبطة بالخيار قبل أن تقرر الخطوة التالية، من دون وعود أو رسوم غير موثقة."],
    ["ماذا يحدث لبياناتي؟", "تُستخدم البيانات التي تدخلها لتجهيز رسالة طلبك وفتحها في واتساب. لا نحفظ بيانات النموذج في المتصفح ولا نرسلها إلى التحليلات."],
  ];
  const configuredFaqs = Array.isArray(content.faqs) ? content.faqs.flatMap((item) => typeof item === "object" && item && typeof (item as Record<string, unknown>).question === "string" && typeof (item as Record<string, unknown>).answer === "string" ? [[String((item as Record<string, unknown>).question), String((item as Record<string, unknown>).answer)]] : []) : [];
  const faqs = configuredFaqs.length ? configuredFaqs : defaultFaqs;
  return <div className="relative bg-[#f7f3e9] text-[#164a43]">
    <section className="border-b border-[#dce3dc] px-5 py-16 md:px-10 md:py-24"><div className="mx-auto grid max-w-[1120px] gap-12 lg:grid-cols-[.8fr_1.2fr]"><div><Pill>لماذا المطابقة؟</Pill><h2 className="font-display mt-5 text-3xl font-bold leading-[1.4] md:text-5xl">القائمة وحدها لا تصف يوم بيتك.</h2></div><div className="grid gap-7 sm:grid-cols-2"><div><h3 className="font-bold">نقل خدمات، لا استقدام جديد</h3><p className="mt-3 text-sm leading-8 text-[#687b72]">الرحلة هنا موجهة لمن يبحث عن خيار نقل خدمات متاح، وتختلف تفاصيلها عن رحلة الاستقدام.</p></div><div><h3 className="font-bold">الاحتياج قبل الملف</h3><p className="mt-3 text-sm leading-8 text-[#687b72]">المدينة والتوقيت وطبيعة المهام والخبرة التي تهمك تساعد على تكوين صورة أوضح قبل مناقشة أي خيار.</p></div></div></div></section>
    <section className="bg-[#edf1e9] px-5 py-16 md:px-10 md:py-24"><div className="mx-auto max-w-[1120px]"><div className="max-w-2xl"><Pill>ما الذي نطابقه؟</Pill><h2 className="font-display mt-5 text-3xl font-bold md:text-5xl">تفاصيل عملية، مرتبطة باحتياجك.</h2></div><div className="mt-12 grid border-y border-[#ced9d0] sm:grid-cols-2 lg:grid-cols-4">{[["المدينة", "مكان العمل الفعلي"], ["التوقيت", "متى ترغب في البدء"], ["مهام المنزل", "الأطفال والمنزل والطبخ والرعاية"], ["التفضيلات", "اللغة والخبرة والجنسية إن كانت مهمة"]].map(([title, copy], index) => <div key={title} className={cn("px-1 py-6 sm:p-6", index > 0 && "sm:border-r sm:border-[#ced9d0]")}><span className="text-xs font-bold text-[#ae814a]">0{index + 1}</span><h3 className="mt-4 font-bold">{title}</h3><p className="mt-2 text-sm leading-7 text-[#6b7c74]">{copy}</p></div>)}</div></div></section>
    <section className="px-5 py-16 md:px-10 md:py-24"><div className="mx-auto grid max-w-[1120px] gap-14 lg:grid-cols-2"><div><Pill>الخطوات</Pill><div className="mt-8 space-y-7">{[["01", "صف احتياج البيت", "نموذج قصير من خطوتين، بالأسئلة المعتمدة فقط."], ["02", "راجع رسالة الطلب", "نجهز رسالة منظمة من اختياراتك من دون تخزينها محلياً."], ["03", "أكمل عبر واتساب", "تفتح المحادثة مع رقم عهد الموثوق من إعدادات النظام."]].map(([number, title, copy]) => <div key={number} className="flex gap-5 border-b border-[#dce3dc] pb-7"><span className="text-sm font-bold text-[#ae814a]">{number}</span><div><h3 className="font-bold">{title}</h3><p className="mt-2 text-sm leading-7 text-[#687b72]">{copy}</p></div></div>)}</div></div><div className="border-r-2 border-[#d6b56d] pr-7 md:pr-10"><Pill>ما الذي تحصل عليه؟</Pill><h2 className="font-display mt-5 text-3xl font-bold leading-[1.45] md:text-5xl">بداية مرتبة، ومعلومات أوضح قبل القرار.</h2><p className="mt-6 text-sm leading-8 text-[#687b72]">المطابقة تساعد على تضييق نطاق النقاش بحسب وصفك. لا تعني ضمان التوفر أو نتيجة محددة، وتبقى مراجعة التفاصيل والقرار النهائي لك.</p><div className="mt-8 border-t border-[#dce3dc] pt-6"><h3 className="font-bold">التكلفة والتفاصيل</h3><p className="mt-2 text-sm leading-8 text-[#687b72]">لا ننشر رقماً عاماً غير موثق. تُوضح معلومات كل خيار وحالة النقل أثناء التواصل وقبل اعتماد أي خطوة.</p></div></div></div></section>
    <section className="bg-[#164a43] px-5 py-16 text-[#f7f3e9] md:px-10 md:py-24"><div className="mx-auto grid max-w-[1120px] gap-12 lg:grid-cols-[.8fr_1.2fr]"><div><span className="text-xs font-bold text-[#d6b56d]">مناسب لك عندما</span><h2 className="font-display mt-5 text-3xl font-bold leading-[1.4] md:text-5xl">تبحث عن نقل خدمات وتريد بدء النقاش من احتياجك.</h2></div><div className="grid gap-8 sm:grid-cols-2"><div><h3 className="font-bold text-[#ead9ae]">هذه الرحلة لك</h3><ul className="mt-4 space-y-3 text-sm leading-7 text-[#c2d1ca]"><li>إذا كانت المدينة والتوقيت والمهام عوامل مهمة.</li><li>إذا لم تكن قد حددت عاملة بعينها.</li><li>إذا كنت مستعداً لمراجعة التفاصيل عبر واتساب.</li></ul></div><div><h3 className="font-bold text-[#ead9ae]">ليست هذه الرحلة</h3><ul className="mt-4 space-y-3 text-sm leading-7 text-[#c2d1ca]"><li>طلب حجز بالساعة.</li><li>وعداً بالتوفر أو القبول أو مدة إنجاز محددة.</li><li>بديلاً عن مراجعة متطلبات النقل الرسمية.</li></ul></div></div></div></section>
    <section className="px-5 py-16 md:px-10 md:py-24"><div className="mx-auto max-w-[900px]"><Pill>الأسئلة الشائعة</Pill><h2 className="font-display mt-5 text-3xl font-bold md:text-5xl">قبل أن تبدأ.</h2><div className="mt-10 divide-y divide-[#d7dfd8] border-y border-[#d7dfd8]">{faqs.map(([question, answer]) => <details key={question} className="group py-5"><summary className="flex cursor-pointer list-none items-center justify-between gap-4 font-bold"><span>{question}</span><ChevronDown className="shrink-0 transition group-open:rotate-180" size={18} /></summary><p className="max-w-3xl pt-4 text-sm leading-8 text-[#687b72]">{answer}</p></details>)}</div></div></section>
    <section className="border-t border-[#dce3dc] bg-[#edf1e9] px-5 py-16 text-center md:px-10 md:py-24"><div className="mx-auto max-w-[720px]"><Pill>طلب من خطوتين</Pill><h2 className="font-display mt-5 text-3xl font-bold leading-[1.4] md:text-5xl">ابدأ بما تعرفه الآن.</h2><p className="mx-auto mt-5 max-w-xl text-sm leading-8 text-[#687b72]">أجب عن تفاصيل البيت الأساسية، ثم أكمل الطلب في محادثة واتساب مع عهد.</p><button onClick={start} className="mt-8 inline-flex items-center gap-3 rounded-full bg-[#164a43] px-7 py-4 text-sm font-bold text-white hover:bg-[#0e3b35]">ابدأ طلب المطابقة<ArrowLeft size={18} /></button></div></section>
  </div>;
}

function Progress({ step }: { step: 1 | 2 }) {
  return <div className="mb-9 flex items-center gap-3 text-xs"><span className="font-bold text-[#164a43]">طلب المطابقة</span><div className="h-px w-10 bg-[#d2dcd3]" />{[1, 2].map((number) => <span key={number} className={cn("flex h-7 w-7 items-center justify-center rounded-full text-[11px] font-bold", step >= number ? "bg-[#164a43] text-[#f7f3e9]" : "bg-[#e7eee6] text-[#82918a]")}>{step > number ? <Check size={14} /> : number}</span>)}</div>;
}
function FormShell({ children, step, navigate }: { children: ReactNode; step: 1 | 2; navigate: Navigate }) {
  return <div dir="rtl" className="min-h-[100dvh] bg-[#f7f3e9] text-[#164a43]"><header className="border-b border-[#dde2da] bg-[#fbfaf6] px-5 py-4 md:px-10"><div className="mx-auto flex max-w-[760px] items-center justify-between"><button data-testid="form-logo" onClick={() => navigate("/")}><Logo /></button><button data-testid="button-exit-form" onClick={() => navigate("/")} className="flex items-center gap-2 text-xs text-[#788982] hover:text-[#164a43]"><X size={15} /> خروج</button></div></header><main className="mx-auto max-w-[760px] px-5 pb-24 pt-10 md:px-10 md:pt-16"><Progress step={step} />{children}</main></div>;
}
function Choice({ label, selected, onClick, detail }: { label: string; selected: boolean; onClick: () => void; detail?: string }) {
  return <button data-testid={`choice-${label}`} onClick={onClick} aria-pressed={selected} className={cn("flex w-full items-center justify-between rounded-2xl border p-4 text-right transition", selected ? "border-[#164a43] bg-[#eef3ed] text-[#164a43]" : "border-[#d8ded7] bg-[#fbfaf6] text-[#49615a] hover:border-[#9eb2a7]")}><span><span className="block text-sm font-bold">{label}</span>{detail && <span className="mt-1 block text-xs text-[#819089]">{detail}</span>}</span><span className={cn("flex h-5 w-5 items-center justify-center rounded-full border", selected ? "border-[#164a43] bg-[#164a43] text-[#f7f3e9]" : "border-[#b8c5bd]")}>{selected && <Check size={12} />}</span></button>;
}
function MatchForm({ step, form, setForm, navigate, whatsappNumber }: { step: 1 | 2; form: FormData; setForm: Dispatch<SetStateAction<FormData>>; navigate: Navigate; whatsappNumber: string }) {
  const [error, setError] = useState("");
  useEffect(() => { if (step === 1) trackEvent("matching_form_started"); }, [step]);
  const update = (key: keyof FormData, value: string | boolean | string[]) => setForm((current) => ({ ...current, [key]: value }));
  const chooseNeed = (need: string) => update("needs", form.needs.includes(need) ? form.needs.filter((item) => item !== need) : [...form.needs, need]);
  if (step === 1) return <FormShell step={1} navigate={navigate}><div className="max-w-[620px] animate-rise-in"><Pill>الخطوة الأولى من اثنتين</Pill><h1 className="font-display mt-5 text-3xl font-bold tracking-[-.04em] md:text-5xl">خلّنا نفهم يومك أكثر.</h1><p className="mt-4 text-[15px] leading-8 text-[#6d7d75]">إجابات بسيطة تساعدنا نكوّن صورة أولية عن احتياج بيتك.</p><div className="mt-9 space-y-7">
    <div><label className="mb-3 block text-sm font-bold">في أي مدينة سيكون العمل؟</label><div className="grid gap-3 sm:grid-cols-3">{["الرياض", "جدة", "مدينة أخرى"].map((city) => <Choice key={city} label={city} selected={form.city === city} onClick={() => update("city", city)} />)}</div></div>
    <div><label className="mb-3 block text-sm font-bold">متى تحتاج البدء؟</label><div className="grid gap-3 sm:grid-cols-3">{["في أسرع وقت", "خلال شهر", "أستكشف فقط"].map((urgency) => <Choice key={urgency} label={urgency} selected={form.urgency === urgency} onClick={() => update("urgency", urgency)} />)}</div></div>
    <div><label className="mb-3 block text-sm font-bold">ما الاحتياج في المنزل؟</label><div className="grid gap-3 sm:grid-cols-2">{["رعاية الأطفال", "شؤون المنزل", "رعاية كبير سن", "طبخ منزلي"].map((need) => <Choice key={need} label={need} selected={form.needs.includes(need)} onClick={() => chooseNeed(need)} />)}</div></div>
    <div><label className="mb-3 block text-sm font-bold">هل تفضّل لغة معيّنة؟ <span className="font-normal text-[#94a09a]">(اختياري)</span></label><div className="grid gap-3 sm:grid-cols-3">{["العربية", "الإنجليزية", "لا يهم"].map((language) => <Choice key={language} label={language} selected={form.languagePreference === language} onClick={() => update("languagePreference", language)} />)}</div></div>
    <div><label className="mb-3 block text-sm font-bold">هل تهمك الخبرة السابقة في السعودية؟ <span className="font-normal text-[#94a09a]">(اختياري)</span></label><div className="grid gap-3 sm:grid-cols-3">{["مهمة", "ليست شرطاً", "لا يهم"].map((value) => <Choice key={value} label={value} selected={form.saudiExperiencePreference === value} onClick={() => update("saudiExperiencePreference", value)} />)}</div></div>
  </div>{error && <p data-testid="status-form-error" className="mt-5 rounded-xl bg-[#f6e8e2] px-4 py-3 text-sm text-[#9b5142]">{error}</p>}<div className="mt-9 flex items-center justify-between"><button data-testid="button-match-back" onClick={() => navigate("/")} className="text-sm font-bold text-[#71817a] hover:text-[#164a43]">رجوع</button><button data-testid="button-match-next" onClick={() => { if (!form.city || !form.urgency || !form.needs.length) { setError("اختر المدينة والتوقيت واحتياجاً واحداً على الأقل."); return; } setError(""); trackEvent("matching_step_1_completed", { needsCount: form.needs.length }); navigate("/match/2"); }} className="flex items-center gap-3 rounded-full bg-[#164a43] px-6 py-3.5 text-sm font-bold text-[#f7f3e9] hover:bg-[#0e3b35]">التالي <ArrowLeft size={17} /></button></div></div></FormShell>;
  return <FormShell step={2} navigate={navigate}><div className="max-w-[620px] animate-rise-in"><Pill>الخطوة الثانية من اثنتين</Pill><h1 className="font-display mt-5 text-3xl font-bold tracking-[-.04em] md:text-5xl">بقيت لمساتك الأخيرة.</h1><p className="mt-4 text-[15px] leading-8 text-[#6d7d75]">اختر ما يهمك، واترك لنا طريقة مناسبة للعودة إليك.</p><div className="mt-9 space-y-7">
    <div className="grid gap-4 sm:grid-cols-2"><label className="block"><span className="mb-2 block text-sm font-bold">الاسم</span><input data-testid="input-match-name" required value={form.name} onChange={(e) => update("name", e.target.value)} placeholder="كيف نناديك؟" className="w-full rounded-2xl border border-[#d8ded7] bg-[#fbfaf6] px-4 py-3.5 text-sm outline-none placeholder:text-[#a0aaa4] focus:border-[#164a43]" /></label><label className="block"><span className="mb-2 block text-sm font-bold">رقم الجوال</span><input data-testid="input-match-phone" required value={form.phone} onChange={(e) => update("phone", e.target.value)} placeholder="05XXXXXXXX" inputMode="tel" className="w-full rounded-2xl border border-[#d8ded7] bg-[#fbfaf6] px-4 py-3.5 text-sm outline-none placeholder:text-[#a0aaa4] focus:border-[#164a43]" /></label></div>
    <label className="block"><span className="mb-2 block text-sm font-bold">الجنسية المفضلة <span className="font-normal text-[#94a09a]">(اختياري)</span></span><input data-testid="input-match-nationality" value={form.nationalityPreference} onChange={(e) => update("nationalityPreference", e.target.value)} placeholder="مثلاً: الفلبين" className="w-full rounded-2xl border border-[#d8ded7] bg-[#fbfaf6] px-4 py-3.5 text-sm outline-none placeholder:text-[#a0aaa4] focus:border-[#164a43]" /></label>
    <div><label className="mb-3 block text-sm font-bold">ما مدى استعدادك؟</label><div className="grid gap-3 sm:grid-cols-3">{["مباشرة", "خلال شهر", "أستكشف فقط"].map((readiness) => <Choice key={readiness} label={readiness} selected={form.readiness === readiness} onClick={() => update("readiness", readiness)} />)}</div></div>
    <label className="flex items-start gap-3 rounded-2xl border border-[#d8ded7] bg-[#fbfaf6] p-4 text-sm"><input data-testid="input-match-consent" type="checkbox" checked={form.consent} onChange={(e) => update("consent", e.target.checked)} className="mt-1 h-4 w-4 accent-[#164a43]" /><span>أوافق على استخدام هذه البيانات للرد على طلب المطابقة عبر واتساب.</span></label>
  </div>{error && <p data-testid="status-form-error" className="mt-5 rounded-xl bg-[#f6e8e2] px-4 py-3 text-sm text-[#9b5142]">{error}</p>}<div className="mt-9 flex items-center justify-between"><button data-testid="button-match-prev" onClick={() => navigate("/match/1")} className="flex items-center gap-2 text-sm font-bold text-[#71817a] hover:text-[#164a43]"><ArrowRight size={16} /> السابق</button><button data-testid="button-match-submit" onClick={() => { const parsed = matchingRequestSchema.safeParse(form); if (!parsed.success) { setError("أكمل الاسم ورقم الجوال والاستعداد ووافق على الخصوصية."); return; } if (!whatsappNumber) { setError("بيانات التواصل غير متاحة حالياً."); return; } const message = buildMatchingRequestMessage(parsed.data); const url = buildWhatsAppUrl(whatsappNumber, message); trackEvent("matching_step_2_completed"); trackEvent("matching_whatsapp_clicked"); window.open(url, "_blank", "noopener,noreferrer"); navigate("/match/thanks"); }} className="flex items-center gap-3 rounded-full bg-[#164a43] px-6 py-3.5 text-sm font-bold text-[#f7f3e9] hover:bg-[#0e3b35]">إرسال الطلب <ArrowLeft size={17} /></button></div></div></FormShell>;
}

function ThankYou({ form, navigate, whatsappNumber }: { form: FormData; navigate: Navigate; whatsappNumber: string }) {
  const parsed = matchingRequestSchema.safeParse(form);
  if (!parsed.success) return <div dir="rtl" className="min-h-[100dvh] bg-[#f7f3e9] text-[#164a43]"><header className="border-b border-[#dde2da] bg-[#fbfaf6] px-5 py-4 md:px-10"><div className="mx-auto max-w-[760px]"><button data-testid="thanks-logo" onClick={() => navigate("/home")}><Logo /></button></div></header><main className="mx-auto max-w-[760px] px-5 pb-24 pt-16 text-center md:pt-24"><Pill>طلب جديد</Pill><h1 className="font-display mx-auto mt-5 max-w-[600px] text-4xl font-bold tracking-[-.04em] md:text-6xl">ابدأ طلب المطابقة من جديد.</h1><p className="mx-auto mt-5 max-w-[500px] text-[15px] leading-8 text-[#6d7d75]">لا توجد بيانات محفوظة في هذه الصفحة. ابدأ طلباً جديداً، وسنجهز رسالتك في واتساب بعد إكمال الخطوات.</p><button data-testid="button-start-matching" onClick={() => navigate("/match/1")} className="mt-8 inline-flex items-center justify-center rounded-full bg-[#164a43] px-6 py-3.5 text-sm font-bold text-[#f7f3e9]">ابدأ طلب المطابقة</button></main></div>;
  const message = buildMatchingRequestMessage(parsed.data);
  const url = whatsappNumber ? buildWhatsAppUrl(whatsappNumber, message) : undefined;
  return <div dir="rtl" className="min-h-[100dvh] bg-[#f7f3e9] text-[#164a43]"><header className="border-b border-[#dde2da] bg-[#fbfaf6] px-5 py-4 md:px-10"><div className="mx-auto max-w-[760px]"><button data-testid="thanks-logo" onClick={() => navigate("/home")}><Logo /></button></div></header><main className="mx-auto max-w-[760px] px-5 pb-24 pt-16 text-center md:pt-24"><div className="mx-auto flex h-16 w-16 items-center justify-center rounded-full bg-[#dcebdd] text-[#164a43]"><Check size={28} /></div><Pill>تم تجهيز طلبك</Pill><h1 className="font-display mx-auto mt-5 max-w-[600px] text-4xl font-bold tracking-[-.04em] md:text-6xl">شكراً، {form.name || "لك"}.</h1><p data-testid="status-thank-you" className="mx-auto mt-5 max-w-[500px] text-[15px] leading-8 text-[#6d7d75]">يمكنك الآن متابعة الحديث معنا على واتساب، أو العودة لاستكشاف المنصة.</p><div className="mx-auto mt-9 max-w-[500px] rounded-3xl border border-[#d8ded7] bg-[#fbfaf6] p-5 text-right"><div className="flex items-center justify-between text-xs text-[#819089]"><span>ملخص الطلب</span><span>مطابقة منزلية</span></div><div className="mt-4 grid grid-cols-2 gap-3 text-sm"><div><span className="block text-xs text-[#8a9891]">المدينة</span><strong className="mt-1 block">{form.city}</strong></div><div><span className="block text-xs text-[#8a9891]">الاحتياج</span><strong className="mt-1 block">{form.needs.join("، ")}</strong></div></div></div><div className="mt-8 flex flex-col justify-center gap-3 sm:flex-row">{url ? <a data-testid="link-whatsapp-match" href={url} target="_blank" rel="noreferrer" className="inline-flex items-center justify-center gap-2 rounded-full bg-[#164a43] px-6 py-3.5 text-sm font-bold text-[#f7f3e9] hover:bg-[#0e3b35]"><MessageCircle size={18} /> متابعة عبر واتساب</a> : <span className="rounded-full bg-[#e7eee6] px-6 py-3.5 text-sm">التواصل غير متاح حالياً</span>}<button data-testid="button-return-site" onClick={() => navigate("/home")} className="rounded-full border border-[#bccbc0] px-6 py-3.5 text-sm font-bold text-[#164a43] hover:bg-[#eef3ed]">العودة للموقع</button></div></main></div>;
}

function HomePage({ navigate }: { navigate: Navigate }) {
  const [faq, setFaq] = useState<number | null>(0);
  const [content, setContent] = useState<Record<string, unknown>>({});
  useEffect(() => { getContent<Record<string, unknown>>("homepage").then((block) => setContent(block.contentAr || {})).catch(() => undefined); }, []);
  const defaultFaqs = [["هل عهد منصة حجز بالساعة؟", "لا. عهد تساعدك على وصف احتياج بيتك واستكشاف خيارات مناسبة لخدمة منزلية مستمرة، ثم تتابع التفاصيل بالطريقة التي تختارها."], ["ماذا يحدث بعد إرسال طلب المطابقة؟", "نرتب طلبك ونساعدك على فهم الخيارات الأقرب لوصفك. يمكنك متابعة النقاش عبر واتساب عندما تكون مستعداً."], ["هل أستطيع البحث بنفسي؟", "نعم، يمكنك استكشاف الكتالوج والتعرّف على الملفات التعريفية، أو ترك التفاصيل لنا عبر طلب المطابقة."]];
  const configuredFaqs = Array.isArray(content.faqs) ? content.faqs.flatMap((item) => typeof item === "object" && item && typeof (item as Record<string, unknown>).question === "string" && typeof (item as Record<string, unknown>).answer === "string" ? [[String((item as Record<string, unknown>).question), String((item as Record<string, unknown>).answer)]] : []) : [];
  const faqs = configuredFaqs.length ? configuredFaqs : defaultFaqs;
  const text = (key: string, fallback: string) => typeof content[key] === "string" && String(content[key]).trim() ? String(content[key]) : fallback;
  return <div dir="rtl" className="min-h-[100dvh] bg-[#f7f3e9] text-[#164a43]"><Header path="/home" navigate={navigate} /><main>
    <section className="mx-auto grid max-w-[1240px] items-center gap-10 px-5 pb-20 pt-10 md:px-10 md:pb-28 md:pt-20 lg:grid-cols-[1fr_.9fr]"><div className="animate-rise-in"><Pill>{text("heroEyebrow", "عهد — بداية أوضح")}</Pill><h1 className="font-display mt-6 max-w-[620px] text-[41px] font-bold leading-[1.35] tracking-[-.05em] md:text-[65px]">{text("heroTitle", "لبيتِك تفاصيله.")}<br /><span className="text-[#ae814a]">{text("heroAccent", "نسمعها أولاً.")}</span></h1><p className="mt-6 max-w-[530px] text-[16px] leading-8 text-[#6d7d75]">{text("heroBody", "تعرّف على خيارات خدمة منزلية تناسب احتياجك، أو دعنا نساعدك في ترتيب الصورة من البداية.")}</p><div className="mt-8 flex flex-col gap-3 sm:flex-row"><button data-testid="button-home-help" onClick={() => navigate("/help")} className="rounded-full bg-[#164a43] px-6 py-3.5 text-sm font-bold text-[#f7f3e9] hover:bg-[#0e3b35]">ساعدني أجد خياراً</button><button data-testid="button-home-catalogue" onClick={() => navigate("/catalogue")} className="rounded-full border border-[#bfcac1] px-6 py-3.5 text-sm font-bold text-[#164a43] hover:bg-[#eef3ed]">استكشف الخيارات <ArrowLeft className="mr-2 inline" size={16} /></button></div></div>
      <div className="surface-grid animate-rise-in delay-1 relative min-h-[360px] overflow-hidden rounded-[34px] bg-[#dce8dd] p-6 md:min-h-[480px]"><div className="absolute -left-12 top-10 h-64 w-64 rounded-full border border-[#a5bcaf]" /><div className="absolute bottom-[-75px] right-[-50px] h-72 w-72 rounded-full border-[22px] border-[#d0dccf]" /><div className="relative flex h-full min-h-[310px] flex-col justify-between"><div className="flex justify-between text-xs text-[#557168]"><span>01 / عهد</span><span>مساحتك للقرار</span></div><div className="self-end rounded-2xl border border-[#b5c9b8] bg-[#f7f3e9]/90 p-5 backdrop-blur-sm md:w-[280px]"><span className="text-xs text-[#7c9086]">فكرة المنصة</span><h2 className="font-display mt-2 text-2xl font-bold leading-[1.5]">لا قائمة طويلة.<br />بل اختيار مفهوم.</h2><div className="mt-5 flex items-center gap-2 text-xs text-[#678076]"><span className="h-2 w-2 rounded-full bg-[#ae814a]" /> أنت تعرف احتياجك أكثر</div></div><div className="flex items-center gap-3 text-sm font-bold text-[#315d53]"><span className="flex h-9 w-9 items-center justify-center rounded-full bg-[#164a43] text-[#f7f3e9]"><ArrowLeft size={16} /></span> ابدأ من المكان الذي يناسبك</div></div></div>
    </section>
    <section className="border-y border-[#dde3da] bg-[#eef2eb] px-5 py-16 md:px-10 md:py-20"><div className="mx-auto max-w-[1240px]"><div className="max-w-xl"><Pill>ثلاث طرق للبدء</Pill><h2 className="font-display mt-5 text-3xl font-bold md:text-5xl">اختر مساحتك.</h2></div><div className="mt-10 grid gap-4 md:grid-cols-3"><button data-testid="home-card-match" onClick={() => navigate("/help")} className="group rounded-3xl bg-[#164a43] p-6 text-right text-[#f7f3e9] transition hover:-translate-y-1"><UsersRound className="text-[#ead9ae]" /><h3 className="font-display mt-14 text-xl font-bold">ساعدني أجد</h3><p className="mt-3 text-sm leading-7 text-[#bfd0c7]">احكِ لنا عن يومك، ونبدأ من احتياجك.</p><span className="mt-6 inline-flex items-center gap-2 text-xs font-bold text-[#ead9ae]">ابدأ من هنا <ArrowLeft size={15} /></span></button><button data-testid="home-card-catalogue" onClick={() => navigate("/catalogue")} className="rounded-3xl border border-[#ccd8ce] bg-[#f8f5ed] p-6 text-right transition hover:-translate-y-1"><Search className="text-[#ae814a]" /><h3 className="font-display mt-14 text-xl font-bold">استكشف الخيارات</h3><p className="mt-3 text-sm leading-7 text-[#6d7d75]">ملفات تعريفية مختصرة تساعدك على تكوين صورة أولية.</p><span className="mt-6 inline-flex items-center gap-2 text-xs font-bold text-[#164a43]">إلى الكتالوج <ArrowLeft size={15} /></span></button><button data-testid="home-card-question" onClick={() => document.getElementById("faq")?.scrollIntoView({ behavior: "smooth" })} className="rounded-3xl border border-[#ccd8ce] bg-[#d9e5d9] p-6 text-right transition hover:-translate-y-1"><CircleHelp className="text-[#164a43]" /><h3 className="font-display mt-14 text-xl font-bold">لدي سؤال</h3><p className="mt-3 text-sm leading-7 text-[#557168]">إجابات مباشرة قبل أن تبدأ.</p><span className="mt-6 inline-flex items-center gap-2 text-xs font-bold text-[#164a43]">الأسئلة الشائعة <ArrowLeft size={15} /></span></button></div></div></section>
    <section id="faq" className="mx-auto max-w-[900px] px-5 py-20 md:px-10 md:py-28"><div className="text-center"><Pill>قبل أن تبدأ</Pill><h2 className="font-display mt-5 text-3xl font-bold md:text-5xl">أسئلة في مكانها.</h2></div><div className="mt-10 border-t border-[#ccd8ce]">{faqs.map(([question, answer], index) => <div key={question} className="border-b border-[#ccd8ce]"><button data-testid={`faq-question-${index}`} onClick={() => setFaq(faq === index ? null : index)} className="flex w-full items-center justify-between gap-4 py-6 text-right font-bold"><span>{question}</span><ChevronDown size={19} className={cn("shrink-0 transition-transform", faq === index && "rotate-180")} /></button>{faq === index && <p data-testid={`faq-answer-${index}`} className="max-w-2xl pb-6 text-sm leading-8 text-[#6d7d75]">{answer}</p>}</div>)}</div></section>
  </main><Footer navigate={navigate} /></div>;
}

function ApiCatalogue({ navigate }: { navigate: Navigate }) {
  const [query, setQuery] = useState("");
  const [skill, setSkill] = useState("الكل");
  const [nationality, setNationality] = useState("الكل");
  const [availability, setAvailability] = useState("الكل");
  const [nationalities, setNationalities] = useState<Array<{ id: string; slug: string; nameAr: string; nameEn: string }>>([]);
  const [skillOptions, setSkillOptions] = useState<Array<{ id: string; slug: string; nameAr: string; nameEn: string }>>([]);
  const [filterOpen, setFilterOpen] = useState(false);
  const [items, setItems] = useState<Worker[]>([]);
  const [loading, setLoading] = useState(true);
  const [workerError, setWorkerError] = useState("");
  const [taxonomyError, setTaxonomyError] = useState("");
  const error = workerError || taxonomyError;
  useEffect(() => {
    let active = true;
    Promise.all([getNationalities(), getSkills()]).then(([countries, taxonomySkills]) => { if (active) { setNationalities(countries); setSkillOptions(taxonomySkills); setTaxonomyError(""); } }).catch((reason: unknown) => { if (active) setTaxonomyError(reason instanceof Error ? reason.message : "تعذر تحميل خيارات التصفية."); });
    return () => { active = false; };
  }, []);
  useEffect(() => {
    let active = true;
    setLoading(true);
    setWorkerError("");
    getWorkers({ nationality: nationality === "الكل" ? undefined : nationality, availability: availability === "الكل" ? undefined : availability, skill: skill === "الكل" ? undefined : skill }).then((workers) => { if (active) setItems(workers.map(mapWorker)); }).catch((reason: unknown) => { if (active) setWorkerError(reason instanceof Error ? reason.message : "تعذر تحميل الكتالوج."); }).finally(() => { if (active) setLoading(false); });
    trackEvent("worker_listing_viewed");
    return () => { active = false; };
  }, [nationality, availability, skill]);
  const filtered = useMemo(() => items.filter((worker) => !query.trim() || `${worker.name} ${worker.origin} ${worker.publicCode} ${worker.skills.join(" ")}`.includes(query.trim())), [items, query]);
  const skills = [{ slug: "الكل", nameAr: "الكل", nameEn: "All" }, ...skillOptions];
  return <div dir="rtl" className="min-h-[100dvh] bg-[#f7f3e9] text-[#164a43]"><Header path="/catalogue" navigate={navigate} /><main className="mx-auto max-w-[1240px] px-5 pb-24 pt-10 md:px-10 md:pt-16"><div className="flex flex-col justify-between gap-8 md:flex-row md:items-end"><div className="animate-rise-in"><Pill>الكتالوج</Pill><h1 className="font-display mt-5 text-4xl font-bold tracking-[-.05em] md:text-6xl">تعرّف على الخيارات.</h1><p className="mt-4 max-w-xl text-[15px] leading-8 text-[#6d7d75]">ملفات تعريفية مختصرة للتعرّف الأولي فقط. التفاصيل والتواصل تُرتّب بعد اختيارك.</p></div><button data-testid="button-catalogue-filter" onClick={() => setFilterOpen(!filterOpen)} className="inline-flex items-center gap-2 self-start rounded-full border border-[#bdcbc0] px-4 py-2.5 text-sm font-bold md:hidden"><Filter size={16} /> تصفية</button></div><div className="mt-10 flex flex-col gap-4 border-y border-[#dce2d9] py-5"><label className="relative flex-1"><Search className="absolute right-4 top-3.5 text-[#819089]" size={18} /><input data-testid="input-catalogue-search" aria-label="بحث في الكتالوج" type="search" value={query} onChange={(e) => setQuery(e.target.value)} placeholder="ابحثي بالاسم أو المهارة أو البلد" className="w-full rounded-2xl border border-[#d2ddd2] bg-[#fbfaf6] py-3.5 pe-11 ps-4 text-sm outline-none focus:border-[#164a43]" /></label><div className={cn("flex flex-wrap gap-2", !filterOpen && "hidden md:flex")}><select data-testid="filter-nationality" aria-label="تصفية حسب الجنسية" value={nationality} onChange={(event) => setNationality(event.target.value)} className="rounded-full border border-[#c8d5ca] bg-[#fbfaf6] px-4 py-2.5 text-xs font-bold text-[#47655c]"><option value="الكل">كل الجنسيات</option>{nationalities.map((item) => <option key={item.slug} value={item.slug}>{item.nameAr || item.nameEn}</option>)}</select><select data-testid="filter-availability" aria-label="تصفية حسب التوفر" value={availability} onChange={(event) => setAvailability(event.target.value)} className="rounded-full border border-[#c8d5ca] bg-[#fbfaf6] px-4 py-2.5 text-xs font-bold text-[#47655c]"><option value="الكل">كل حالات التوفر</option><option value="AVAILABLE">متاحة للتواصل</option><option value="ON_HOLD">متوقفة مؤقتاً</option><option value="RESERVED">محجوزة</option><option value="TRANSFER_IN_PROGRESS">إجراءات النقل جارية</option><option value="UNAVAILABLE">غير متاحة</option></select>{skills.map((item) => <button data-testid={`filter-skill-${item.slug}`} key={item.slug} onClick={() => setSkill(item.slug)} className={cn("rounded-full px-4 py-2.5 text-xs font-bold transition", skill === item.slug ? "bg-[#164a43] text-[#f7f3e9]" : "bg-[#e7efe6] text-[#47655c] hover:bg-[#dce8dc]")}>{item.nameAr || item.nameEn}</button>)}</div></div>{error && <p role="alert" className="mt-5 rounded-xl bg-[#f6e8e2] px-4 py-3 text-sm text-[#9b5142]">{error}</p>}<div className="mt-8 flex items-center justify-between text-sm text-[#6d7d75]"><span data-testid="text-catalogue-count">{loading ? "..." : error ? "تعذر تحميل النتائج" : `${filtered.length} ملفات تعريفية`}</span><span className="hidden items-center gap-2 md:flex"><ShieldCheck size={15} /> بيانات منشورة من الإدارة</span></div>{loading ? <div className="mt-5 grid gap-5 sm:grid-cols-2 lg:grid-cols-4">{[1, 2, 3, 4].map((item) => <div key={item} className="h-[350px] animate-pulse rounded-3xl border border-[#d5ded4] bg-[#fbfaf6]" />)}</div> : error ? null : filtered.length ? <div className="mt-5 grid gap-5 sm:grid-cols-2 lg:grid-cols-4">{filtered.map((worker) => <button data-testid={`card-worker-${worker.id}`} key={worker.id} onClick={() => navigate(`/catalogue/${worker.slug}`)} className="group overflow-hidden rounded-3xl border border-[#d5ded4] bg-[#fbfaf6] text-right transition hover:-translate-y-1 hover:border-[#9eb5a5]"><WorkerMark worker={worker} /><div className="p-5"><div className="flex items-start justify-between gap-3"><div><h2 className="font-display text-lg font-bold">{worker.name}</h2><p className="mt-1 text-xs text-[#778880]">{worker.origin} · {worker.publicCode}</p></div><ChevronLeft size={17} className="text-[#8a9a91] transition group-hover:-translate-x-1" /></div><p className="mt-4 text-sm text-[#4d675e]">{worker.experience}</p><div className="mt-4 flex flex-wrap gap-1.5">{worker.skills.slice(0, 2).map((item) => <span key={item} className="rounded-full bg-[#e8efe7] px-2.5 py-1 text-[10px] text-[#527066]">{item}</span>)}</div><p className="mt-5 border-t border-[#e0e5df] pt-4 text-xs font-bold text-[#6b8178]">{worker.availability}</p></div></button>)}</div> : <div data-testid="catalogue-empty" className="mt-8 rounded-3xl border border-dashed border-[#b8c9bc] bg-[#edf2eb] px-6 py-16 text-center"><Search className="mx-auto text-[#718a7d]" /><h2 className="font-display mt-4 text-xl font-bold">لا توجد ملفات منشورة حالياً.</h2><p className="mt-2 text-sm text-[#6d7d75]">جرّبي بحثاً آخر أو ابدئي طلب المطابقة.</p><button onClick={() => navigate("/")} className="mt-6 rounded-full bg-[#164a43] px-5 py-3 text-sm font-bold text-[#f7f3e9]">ابدئي طلب المطابقة</button></div>}</main><Footer navigate={navigate} /></div>;
}

function ApiProfile({ slug, navigate, whatsappNumber }: { slug: string; navigate: Navigate; whatsappNumber: string }) {
  const [worker, setWorker] = useState<Worker | null>(null);
  const [loading, setLoading] = useState(true);
  const [loadError, setLoadError] = useState("");
  const [formError, setFormError] = useState("");
  const [name, setName] = useState("");
  const [city, setCity] = useState("");
  const [phone, setPhone] = useState("");
  const [note, setNote] = useState("");
  const [submitted, setSubmitted] = useState(false);
  useEffect(() => { let active = true; getWorker(slug).then((result) => { if (active) { const mapped = mapWorker(result); setWorker(mapped); trackEvent("worker_profile_viewed", { workerRef: mapped.publicCode }); } }).catch((reason: unknown) => { if (active) setLoadError(reason instanceof Error ? reason.message : "تعذر تحميل الملف."); }).finally(() => { if (active) setLoading(false); }); return () => { active = false; }; }, [slug]);
  if (loading) return <div dir="rtl" className="min-h-[100dvh] bg-[#f7f3e9] text-[#164a43]"><Header path="/catalogue" navigate={navigate} /><main className="mx-auto max-w-[1040px] px-5 pb-24 pt-14 md:px-10"><div className="h-[500px] animate-pulse rounded-[32px] bg-[#e7eee6]" /></main></div>;
  if (loadError) return <div dir="rtl" className="min-h-[100dvh] bg-[#f7f3e9] text-[#164a43]"><Header path="/catalogue" navigate={navigate} /><main className="mx-auto max-w-[1040px] px-5 py-20 md:px-10"><p role="alert" className="rounded-xl bg-[#f6e8e2] px-4 py-3 text-sm text-[#9b5142]">{loadError}</p></main></div>;
  if (!worker) return <NotFound navigate={navigate} />;
  const formInput = { workerPublicCode: worker.publicCode, workerDisplayName: worker.name, name, city, phone, note };
  const parsed = workerRequestFormSchema.safeParse(formInput);
  const url = parsed.success && whatsappNumber ? buildWhatsAppUrl(whatsappNumber, buildWorkerRequestMessage(formInput)) : undefined;
  const handleSubmit = () => { setFormError(""); if (!parsed.success) { setFormError("أكمل الاسم والمدينة ورقم الجوال بشكل صحيح."); return; } if (!whatsappNumber || !worker.requestable) { setFormError("هذا الملف غير متاح للتواصل حالياً."); return; } trackEvent("worker_request_started", { workerRef: worker.publicCode }); trackEvent("worker_whatsapp_clicked", { workerRef: worker.publicCode }); window.open(url, "_blank", "noopener,noreferrer"); setSubmitted(true); };
  return <div dir="rtl" className="min-h-[100dvh] bg-[#f7f3e9] text-[#164a43]"><Header path="/catalogue" navigate={navigate} /><main className="mx-auto max-w-[1040px] px-5 pb-24 pt-8 md:px-10 md:pt-14"><button data-testid="button-profile-back" onClick={() => navigate("/catalogue")} className="mb-8 inline-flex items-center gap-2 text-sm font-bold text-[#71817a] hover:text-[#164a43]"><ArrowRight size={16} /> العودة للخيارات</button><div className="grid gap-8 lg:grid-cols-[1fr_360px]"><section className="rounded-[32px] border border-[#d6dfd5] bg-[#fbfaf6] p-6 md:p-9"><div className="flex flex-col gap-6 sm:flex-row sm:items-start"><WorkerMark worker={worker} small /><div><Pill>ملف تعريفي</Pill><h1 data-testid="text-worker-name" className="font-display mt-3 text-3xl font-bold">{worker.name}</h1><p className="mt-2 text-sm text-[#73847c]">{worker.origin} · {worker.publicCode}</p></div></div><div className="mt-9 border-t border-[#e0e5df] pt-7"><h2 className="font-display text-xl font-bold">نبذة مختصرة</h2><p className="mt-3 max-w-2xl text-[15px] leading-8 text-[#5e746b]">{worker.story}</p></div><div className="mt-8 grid gap-7 sm:grid-cols-2"><div><h3 className="text-sm font-bold">المهارات</h3><div className="mt-3 flex flex-wrap gap-2">{worker.skills.map((item) => <span key={item} className="rounded-full bg-[#e8efe7] px-3 py-1.5 text-xs text-[#4b6b60]">{item}</span>)}</div></div><div><h3 className="text-sm font-bold">اللغات</h3><div className="mt-3 flex flex-wrap gap-2">{worker.languages.map((item) => <span key={item} className="rounded-full border border-[#d1ddd1] px-3 py-1.5 text-xs text-[#5e746b]">{item}</span>)}</div></div></div></section><aside className="h-fit rounded-[32px] bg-[#164a43] p-6 text-[#f7f3e9] md:p-7"><div className="flex items-center gap-2 text-[#ead9ae]"><UserRound size={17} /><span className="text-sm font-bold">اطلب هذه العاملة</span></div>{submitted && url ? <div data-testid="status-profile-submitted" className="py-10 text-center"><span className="mx-auto flex h-12 w-12 items-center justify-center rounded-full bg-[#dcebdd] text-[#164a43]"><Check /></span><h2 className="font-display mt-5 text-xl font-bold">تم فتح واتساب.</h2><a data-testid="link-whatsapp-profile" href={url} target="_blank" rel="noreferrer" className="mt-6 inline-flex items-center gap-2 rounded-full bg-[#ead9ae] px-5 py-3 text-sm font-bold text-[#164a43]"><MessageCircle size={16} /> متابعة عبر واتساب</a></div> : <><p className="mt-3 text-sm leading-7 text-[#c2d2c9]">اترك بيانات بسيطة لنرفق رقم الملف تلقائياً في رسالة واتساب.</p><div className="mt-6 space-y-4"><label className="block text-sm"><span className="mb-2 block text-[#dbe7df]">الاسم</span><input data-testid="input-profile-name" required autoComplete="name" value={name} onChange={(e) => setName(e.target.value)} className="w-full rounded-xl border border-[#60857a] bg-[#245b52] px-3.5 py-3 text-sm text-[#f7f3e9] outline-none placeholder:text-[#9fb8ad] focus:border-[#ead9ae]" placeholder="كيف نناديك؟" /></label><label className="block text-sm"><span className="mb-2 block text-[#dbe7df]">المدينة</span><input data-testid="input-profile-city" required value={city} onChange={(e) => setCity(e.target.value)} className="w-full rounded-xl border border-[#60857a] bg-[#245b52] px-3.5 py-3 text-sm text-[#f7f3e9] outline-none placeholder:text-[#9fb8ad]" placeholder="مدينة السكن" /></label><label className="block text-sm"><span className="mb-2 block text-[#dbe7f9]">رقم الجوال</span><input data-testid="input-profile-phone" required autoComplete="tel" value={phone} onChange={(e) => setPhone(e.target.value)} inputMode="tel" className="w-full rounded-xl border border-[#60857a] bg-[#245b52] px-3.5 py-3 text-sm text-[#f7f3e9] outline-none" placeholder="05XXXXXXXX" /></label><label className="block text-sm"><span className="mb-2 block text-[#dbe7df]">ملاحظة <span className="text-[#a9c0b5]">(اختياري)</span></span><textarea data-testid="input-profile-note" value={note} onChange={(e) => setNote(e.target.value)} rows={3} className="w-full resize-none rounded-xl border border-[#60857a] bg-[#245b52] px-3.5 py-3 text-sm text-[#f7f3e9] outline-none placeholder:text-[#9fb8ad]" placeholder="ما الذي تريد معرفته؟" /></label></div>{formError && <p role="alert" data-testid="status-profile-error" className="mt-4 rounded-xl bg-[#6e3f38] px-3 py-2 text-xs text-[#f6ddd4]">{formError}</p>}<button data-testid="button-profile-submit" onClick={handleSubmit} className="mt-6 w-full rounded-full bg-[#ead9ae] px-5 py-3.5 text-sm font-bold text-[#164a43] hover:bg-[#f3e5bf]">أرسل طلب التواصل</button></>}</aside></div></main><Footer navigate={navigate} /></div>;
}

function WorkerMark({ worker, small = false }: { worker: Worker; small?: boolean }) {
  return <div aria-hidden="true" className={cn("relative flex shrink-0 items-end justify-center overflow-hidden rounded-[24px]", small ? "h-24 w-24" : "h-36 w-full")} style={{ backgroundColor: worker.color }}>{worker.imageUrl ? <img src={worker.imageUrl} alt="" loading="lazy" className="h-full w-full object-cover" /> : <><div className={cn("absolute -top-8 h-24 w-24 rounded-full border-[10px] border-[#f7f3e9]/45", small ? "h-16 w-16" : "h-28 w-28")} /><span className={cn("relative font-display font-bold text-[#164a43]/80", small ? "text-4xl" : "text-6xl")}>{worker.initials}</span></>}</div>;
}

function HelpEntry({ navigate }: { navigate: Navigate }) {
  return <div dir="rtl" className="min-h-[100dvh] bg-[#f7f3e9] text-[#164a43]"><Header path="/help" navigate={navigate} /><main className="mx-auto max-w-[980px] px-5 pb-24 pt-10 md:px-10 md:pt-16"><div className="grid gap-10 lg:grid-cols-[.85fr_1fr] lg:items-start"><section className="animate-rise-in"><Pill>ساعدني أجد</Pill><h1 className="font-display mt-5 text-4xl font-bold leading-[1.4] tracking-[-.05em] md:text-6xl">قل لنا ما الذي<br /><span className="text-[#ae814a]">يهمك فعلاً.</span></h1><p className="mt-5 max-w-md text-[15px] leading-8 text-[#6d7d75]">لا تحتاج إلى معرفة المصطلحات أو الخيارات مسبقاً. ابدأ بطلب المطابقة، وسنرتب الصورة معك.</p><div className="mt-8 space-y-4 text-sm text-[#557168]"><div className="flex items-center gap-3"><span className="flex h-8 w-8 items-center justify-center rounded-full bg-[#dce8dd] text-xs font-bold">١</span> نصف احتياج البيت كما هو</div><div className="flex items-center gap-3"><span className="flex h-8 w-8 items-center justify-center rounded-full bg-[#dce8dd] text-xs font-bold">٢</span> نرتب معك بداية مناسبة</div><div className="flex items-center gap-3"><span className="flex h-8 w-8 items-center justify-center rounded-full bg-[#dce8dd] text-xs font-bold">٣</span> تختار طريقة التواصل</div></div></section><section className="rounded-[32px] border border-[#d6dfd5] bg-[#fbfaf6] p-6 shadow-[0_18px_50px_rgba(28,67,53,.06)] md:p-8"><div className="flex items-center justify-between"><div><h2 className="font-display text-xl font-bold">طلب المطابقة</h2><p className="mt-1 text-xs text-[#819089]">أسئلة قليلة، وصورة أوضح لاحتياجك.</p></div><Sparkles className="text-[#ae814a]" size={20} /></div><div className="mt-7 rounded-2xl bg-[#eef3ed] p-5 text-sm leading-8 text-[#557168]">سنطلب المدينة، التوقيت، الاحتياج، ثم بيانات التواصل اللازمة للرد عبر واتساب.</div><button data-testid="button-help-start-match" onClick={() => { trackEvent("matching_cta_clicked"); navigate("/match/1"); }} className="mt-6 inline-flex w-full items-center justify-center gap-2 rounded-full bg-[#164a43] px-5 py-3.5 text-sm font-bold text-[#f7f3e9] hover:bg-[#0e3b35]">ابدأ طلب المطابقة <ArrowLeft size={17} /></button><button data-testid="button-help-catalogue" onClick={() => navigate("/catalogue")} className="mt-3 inline-flex w-full items-center justify-center rounded-full border border-[#bdcbc0] px-5 py-3.5 text-sm font-bold">استكشاف الخيارات</button></section></div></main><Footer navigate={navigate} /></div>;
}
function NotFound({ navigate }: { navigate: Navigate }) {
  return <div dir="rtl" className="flex min-h-[100dvh] items-center justify-center bg-[#f7f3e9] px-5 text-center text-[#164a43]"><div><Pill>404</Pill><h1 className="font-display mt-5 text-4xl font-bold">هذه الصفحة غير موجودة.</h1><p className="mt-3 text-sm text-[#6d7d75]">جرّب العودة إلى البداية.</p><button data-testid="button-not-found-home" onClick={() => navigate("/home")} className="mt-7 rounded-full bg-[#164a43] px-6 py-3.5 text-sm font-bold text-[#f7f3e9]">العودة للرئيسية</button></div></div>;
}

function Site() {
  const [location, setLocation] = useLocation();
  const [form, setForm] = useState<FormData>(initialForm);
  const { whatsappNumber } = useContext(PublicSettingsContext);
  const navigate = (path: string) => { setLocation(path); window.scrollTo({ top: 0, behavior: "smooth" }); };
  useEffect(() => {
    document.documentElement.lang = "ar"; document.documentElement.dir = "rtl";
    document.title = location.startsWith("/admin") ? "إدارة عهد" : location.startsWith("/catalogue") ? "الخيارات | عهد" : location === "/help" ? "ساعدني أجد | عهد" : "عهد | نقل خدمات منزلية";
    const description = "عهد منصة تساعدك على فهم احتياج بيتك واستكشاف خيارات نقل الخدمات المنزلية.";
    let meta = document.querySelector('meta[name="description"]'); if (!meta) { meta = document.createElement("meta"); meta.setAttribute("name", "description"); document.head.appendChild(meta); } meta.setAttribute("content", description);
  }, [location]);
  const path = location.replace(/\/+$/, "") || "/";
  if (path.startsWith("/admin")) return <AdminApp navigate={navigate} />;
  if (path === "/") return <Landing navigate={navigate} />;
  if (path === "/match/1") return <MatchForm step={1} form={form} setForm={setForm} navigate={navigate} whatsappNumber={whatsappNumber} />;
  if (path === "/match/2") return <MatchForm step={2} form={form} setForm={setForm} navigate={navigate} whatsappNumber={whatsappNumber} />;
  if (path === "/match/thanks") return <ThankYou form={form} navigate={navigate} whatsappNumber={whatsappNumber} />;
  if (path === "/home") return <HomePage navigate={navigate} />;
  if (path === "/catalogue") return <ApiCatalogue navigate={navigate} />;
  if (path.startsWith("/catalogue/")) return <ApiProfile slug={path.split("/")[2]} navigate={navigate} whatsappNumber={whatsappNumber} />;
  if (path === "/help") return <HelpEntry navigate={navigate} />;
  return <NotFound navigate={navigate} />;
}

function App() {
  const [settings, setSettings] = useState({ whatsappNumber: "", phoneNumber: "" });
  useEffect(() => { getPublicSettings().then((value) => setSettings({ whatsappNumber: value.whatsappNumber || "", phoneNumber: value.phoneNumber || "" })).catch(() => setSettings({ whatsappNumber: import.meta.env.VITE_WHATSAPP_NUMBER || "", phoneNumber: import.meta.env.VITE_PHONE_NUMBER || "" })); }, []);
  return <QueryClientProvider client={queryClient}><PublicSettingsContext.Provider value={settings}><TooltipProvider><WouterRouter base={import.meta.env.BASE_URL.replace(/\/$/, "")}><Site /></WouterRouter><Toaster /></TooltipProvider></PublicSettingsContext.Provider></QueryClientProvider>;
}

export default App;
